/* ---------- utilitaires ---------- */
const SEP = /\s+(?:و|w|et|and|x|X|مع)\s+|\s*(?:\+|&|×|<3|[❤♥💕💘💞💑💍🥰😍💖💗💓💝❣])\s*|\s+-\s+/u;
function parse(text){
  const parts = String(text).replace(/\uFE0F/g, '').trim().split(SEP).map(s => s.trim()).filter(Boolean);
  if (parts.length !== 2) return null;
  const ok = n => n.length >= 2 && n.length <= 18 && n.split(/\s+/).length <= 2 && !/https?:|www\./i.test(n);
  return ok(parts[0]) && ok(parts[1]) ? parts : null;
}
const hash = s => { let h = 5381; for (const c of s) h = ((h << 5) + h + c.charCodeAt(0)) >>> 0; return h; };
