setInterval(() => { if (dirty) { dirty = false; bc({ t:'board', ...board() }); save(); } }, 1500);
const qinfo = () => bc({ t:'queue', n:queue.length, list:queue.slice(0, 5).map(q => q.a + ' ❤ ' + q.b) });
function pts(u, kind, n){
  const x = D.users[u.id] || (D.users[u.id] = { id:u.id, name:u.name, pts:0, likes:0, gifts:0 });
  x.name = u.name; x.pts += n*cfg().points[kind]; if (kind === 'like') x.likes += n; if (kind === 'gift') x.gifts += n; dirty = true;
}
function dispatch(){
  if (!waiting || !queue.length) return;
  const it = queue.shift(), force = forceNext || it.boost; forceNext = false;
  let pool = cfg().predictions.filter(p => p.on !== false); if (force) { const f = pool.filter(p => FEST.includes(p.k)); if (f.length) pool = f; }
  if (!pool.length) return;
  const fixed = it.fp != null ? cfg().predictions[it.fp] : null, pred = fixed || pool[it.h % pool.length];
  if (!pred) return; const score = force && !fixed ? pred.hi : pred.lo + (it.h >> 3) % (pred.hi - pred.lo + 1);
  stats.shown++; shown.unshift({ t:Date.now(), a:it.a, b:it.b, tag:pred.tag, k:pred.k, score, by:it.by, boost:!!force }); shown.length = Math.min(shown.length, 15);
  waiting = false; bc({ t:'show', item:it, pred, score, boost:!!force }); qinfo();
}
function enqueue(u, text, manual, fp){
  const c = parse(text); if (!c) { if (!manual) note(text, 'format non reconnu'); return false; }
  const key = c.map(s => s.toLowerCase()).sort().join('|'), now = Date.now(), T = cfg().time;
  if (cfg().banned.some(w => w && (c[0] + ' ' + c[1]).toLowerCase().includes(String(w).toLowerCase()))) { note(text, 'mot interdit'); return true; }
  if (!manual && (seen.get(key) || 0) > now - T.dedupe*1000) { note(text, 'couple déjà vu récemment'); return true; }
  if (!manual && queue.length >= T.queueMax) { note(text, 'file pleine'); return true; }
  seen.set(key, now);
  const it = { a:c[0], b:c[1], h:hash(key), by:u.name, boost:boosts.delete(u.id), fp:fp == null ? undefined : fp };
  manual ? queue.unshift(it) : queue.push(it);
  if (!manual) { pts(u, 'comment', 1); note(text, 'accepté'); }
  qinfo(); dispatch(); return true;
}

/* ---------- TikTok ---------- */
async function startTikTok(pseudo){
  try { await startTT(pseudo); } catch (e) { console.error('TikTok :', e && e.message); }
}
async function startTT(pseudo){
  if (conn) { try { conn.disconnect(); } catch {} conn = null; }
  live = false; bc({ t:'status', ok:false }); pseudo = String(pseudo || '').replace('@', '').trim(); if (!pseudo) return;
  let TikTokLiveConnection, WebcastEvent, ControlEvent;
  try { const m = await import('tiktok-live-connector'); ({ TikTokLiveConnection, WebcastEvent, ControlEvent } = m.TikTokLiveConnection ? m : m.default); }
  catch (e) { console.error('Impossible de charger tiktok-live-connector :', e && e.message); return; }
  const c = conn = new TikTokLiveConnection(pseudo, {});
  c.on(ControlEvent.CONNECTED, () => { live = true; bc({ t:'status', ok:true }); console.log('Connecté au live de @' + pseudo); });
  c.on(ControlEvent.DISCONNECTED, () => { live = false; bc({ t:'status', ok:false }); if (conn === c) setTimeout(() => conn === c && c.connect().catch(() => {}), 5000); });
  c.on(ControlEvent.ERROR, e => console.error('TikTok :', e && (e.message || e)));
  c.on(WebcastEvent.CHAT, d => { cnt.chat++; bump('chat', 1); if (!d.comment) { note('(vide)', 'commentaire sans texte'); return; } enqueue(who(d), d.comment); });
  c.on(WebcastEvent.LIKE, d => {
    cnt.like++; const n = d.likeCount || 1; bump('like', n); pts(who(d), 'like', n); meter += n*cfg().points.meterPerLike;
    if (meter >= 100) { meter = 0; forceNext = true; bc({ t:'mega' }); }
  });
  c.on(WebcastEvent.GIFT, d => {
    const g = d.giftDetails || d; if (g.giftType === 1 && !d.repeatEnd) return;
    cnt.gift++; bump('gift', 1); const dm = (g.diamondCount || d.diamondCount || 1)*(d.repeatCount || 1), u = who(d);
    pts(u, 'gift', dm); boosts.add(u.id); bc({ t:'gift', name:u.name, d:dm });
  });
  c.connect().catch(e => { console.error('Connexion impossible :', e && e.message); setTimeout(() => conn === c && startTikTok(pseudo), 8000); });
}

/* ---------- écran de jeu (WebSocket) ---------- */
wss.on('connection', w => {
  send(w, { t:'config', cfg:cfg() }); send(w, { t:'status', ok:live }); send(w, { t:'board', ...board() });
  w.on('message', m => { let d; try { d = JSON.parse(m); } catch { return; } if (d.t === 'next') { waiting = true; dispatch(); } });
});

/* ---------- pages + API admin ---------- */
const auth = (q, r, n) => q.headers['x-admin'] === PASS ? n() : r.status(401).json({ error:'mot de passe incorrect' });
app.get('/', (q, r) => r.type('html').send(page('index')));
app.get('/admin', (q, r) => r.type('html').send(page('admin')));
app.get('/api/admin/state', auth, (q, r) => r.json({ cfg:cfg(), cnt, recent, shown, series, shownTotal:stats.shown, nu:Object.keys(D.users).length, tp:Object.values(D.users).reduce((n, x) => n + x.pts, 0), since:stats.since, live, meter:Math.round(meter), queue:queue.map(x => x.a + ' ❤ ' + x.b), users:Object.values(D.users).sort((a, b) => b.pts - a.pts).slice(0, 100) }));
app.post('/api/admin/config', auth, (q, r) => {
  if (!q.body || typeof q.body !== 'object') return r.sendStatus(400);
  const old = D.cfg.tiktok; D.cfg = merge(DEF, q.body); save(); bc({ t:'config', cfg:cfg() });
  if (D.cfg.tiktok !== old) startTikTok(D.cfg.tiktok); r.json({ ok:1 });
});
app.post('/api/admin/action', auth, (q, r) => {
  const { type, a, b, pi } = q.body || {};
  if (type === 'skip') bc({ t:'skip' });
  if (type === 'clear') { queue = []; qinfo(); }
  if (type === 'reset') { D.users = {}; meter = 0; dirty = true; save(); }
  if (type === 'mega') { meter = 0; forceNext = true; bc({ t:'mega' }); }
  if (type === 'test' && a && b) enqueue({ id:'admin', name:'Admin' }, a + ' + ' + b, true, Number.isInteger(pi) ? pi : null);
  r.json({ ok:1 });
});

